function fixText(text) {
  if (!text) return '';
  return text
    .replace(/[\u2014]/g, '-')
    .replace(/[\u2013]/g, '-')
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\u2026/g, '...')
    .replace(/\u00A0/g, ' ');
}

