let tableCounter = 0;

function createTableCaption(text) {
    tableCounter++;
    return new Paragraph({
        spacing: { before: 200, after: 100 },
        children: [
            new TextRun({
                text: `Table ${tableCounter}: ${fixText(text)}`,
                bold: true,
                size: 20,
                color: COLORS.CAPTION_GRAY,
                font: 'Arial'
            })
        ]
    });
}

