createTable.codePattern:
function createTable(headers, rows, caption = null) {
  const elements = [];

  // Add caption if provided
  if (caption) {
    elements.push(createTableCaption(caption));
  }
  const headerCells = headers.map(header =>
    new TableCell({
      shading: { fill: COLORS.DARK_TEAL, type: ShadingType.CLEAR },
      verticalAlign: VerticalAlign.CENTER,
      children: [
        new Paragraph({
          alignment: AlignmentType.CENTER,
          spacing: { before: 60, after: 60 },
          children: [
            new TextRun({
              text: fixText(header),
              bold: true,
              color: COLORS.WHITE,
              size: SIZES.TABLE_HEADER,
              font: 'Arial'
            })
          ]
        })
      ],
      borders: {...}
    })
  );

  const dataRows = rows.map((row, rowIndex) => {
    const isAlternate = rowIndex % 2 === 1;
    const cells = row.map((cell, colIndex) =>
      new TableCell({
        shading: isAlternate ? { fill: COLORS.LIGHT_BG, type: ShadingType.CLEAR } : undefined,
        verticalAlign: VerticalAlign.CENTER,
        children: [
          new Paragraph({
            alignment: colIndex === 0 ? AlignmentType.LEFT : AlignmentType.CENTER,
            spacing: { before: 40, after: 40 },
            children: [
              new TextRun({
                text: fixText(String(cell)),
                size: SIZES.TABLE_BODY,
                color: COLORS.BODY_TEXT,
                font: 'Arial'
              })
            ]
          })
        ],
        borders: {...}
      })
    );
    return new TableRow({ children: cells });
  });

  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    rows: [
      new TableRow({ children: headerCells }),
      ...dataRows
    ]
  });
}

createReference.codePattern:
function createReference(text) {
  return new Paragraph({
    spacing: { before: 80, after: 240 },
    children: [
      new TextRun({
        text: fixText(`Source: ${text}`),
        italic: true,
        size: SIZES.REFERENCE,
        color: COLORS.REFERENCE_BLUE,
        font: 'Arial'
      })
    ]
  });
}

createBullets.codePattern:
function createBullets(items) {
  return items.map(item =>
    new Paragraph({
      bullet: { level: 0 },
      spacing: { after: 100, line: 276 },
      children: [
        new TextRun({
          text: fixText(item),
          size: SIZES.BODY_TEXT,
          color: COLORS.BODY_TEXT,
          font: 'Arial'
        })
      ]
    })
  );
}

