function createKeyInsightBox(title, content) {
  return [
    new Paragraph({
      shading: { fill: COLORS.LIGHT_BG, type: ShadingType.CLEAR },
      border: {
        left: { style: BorderStyle.SINGLE, size: 32, color: COLORS.PRIMARY }
      },
      spacing: { before: 200, after: 100 },
      indent: { left: 600 },
      children: [
        new TextRun({
          text: 'KEY INSIGHT',
          bold: true,
          size: SIZES.KEY_INSIGHT_LABEL,
          color: COLORS.PRIMARY,
          font: 'Arial'
        })
      ]
    }),
    new Paragraph({
      shading: { fill: COLORS.LIGHT_BG, type: ShadingType.CLEAR },
      border: {
        left: { style: BorderStyle.SINGLE, size: 32, color: COLORS.PRIMARY }
      },
      spacing: { after: 80 },
      indent: { left: 600 },
      children: [
        new TextRun({
          text: fixText(title),
          bold: true,
          size: SIZES.KEY_INSIGHT_TITLE,
          color: COLORS.BODY_TEXT,
          font: 'Arial'
        })
      ]
    }),
    new Paragraph({
      shading: { fill: COLORS.LIGHT_BG, type: ShadingType.CLEAR },
      border: {
        left: { style: BorderStyle.SINGLE, size: 32, color: COLORS.PRIMARY }
      },
      spacing: { after: 200 },
      indent: { left: 600 },
      alignment: AlignmentType.JUSTIFIED,
      children: [
        new TextRun({
          text: fixText(content),
          size: SIZES.KEY_INSIGHT_CONTENT,
          color: COLORS.BODY_TEXT,
          font: 'Arial'
        })
      ]
    })
  ];
}

